import{_ as e,o as t,c as a,ag as o}from"./chunks/framework.Ddwm6YJC.js";const u=JSON.parse('{"title":"第三卷 潮汐 · 第47章 冷静信","description":"","frontmatter":{},"headers":[],"relativePath":"第47章_冷静信.md","filePath":"第47章_冷静信.md"}'),_={name:"第47章_冷静信.md"};function r(c,p,n,s,l,i){return t(),a("div",null,[...p[0]||(p[0]=[o('<h1 id="第三卷-潮汐-·-第47章-冷静信" tabindex="-1">第三卷 潮汐 · 第47章 冷静信 <a class="header-anchor" href="#第三卷-潮汐-·-第47章-冷静信" aria-label="Permalink to &quot;第三卷 潮汐 · 第47章 冷静信&quot;">​</a></h1><p>高二秋末的风凉了下来，吹过南雾县的街巷，带着雾山市那边的潮气。</p><p>放学后，我在教室里拿到了那封信。林小满把信封塞进我手心，指尖冰凉，指腹还有纸条压出的细痕。</p><p>“江苒让我给你的。”她小声说，“看了就明白了。”</p><p>信封很薄，封口贴着一颗纸星星，折得有点歪，角压不平，留着毛边，一看就是她的手法。</p><p>陈默在后排收拾书包，动作放得很轻，拉链声都压住，书本磕桌角也小心。顾远站在门口，想喊我去走走，又把话咽了回去，手搭在门框上没动。</p><p>我坐回座位，窗外的斜光落在纸星星上，泛出柔和的黄。我用掌心把信封压平，把翘起的角捋伏贴。</p><p>“看吧。”林小满说，“早看早踏实。”</p><p>我撕开封口，纸张摩擦的细响在安静的教室里格外清楚。</p><p>信纸只有两页，字迹起笔很稳，越到后面越轻，墨色也淡了，像手腕慢慢没了力气。</p><blockquote><p>她写：高二的秋天过得真快，南雾县的雾又重了，这几天夜里睡不着，就起来折星星，折满一小罐，又倒出来重新折 她写：很感谢我，难过时找我，害怕时找我，连做梦醒来心慌的那几秒，想到的也是我，可越是这样她越害怕，觉得把太多寄托放在我身上，重到她自己都不安</p></blockquote><p>我能想象那个画面。台灯的光晕里，她低着头，指尖捏着纸条，一圈圈绕着。窗外是雾，鸟叫声很远。</p><p>她写，我也有自己的潮汐要面对，不该替她挡住所有的浪。那句潮汐两个字写得特别慢，笔画都顿了一下。</p><p>看到这里，我手指顿了一下，纸面被捏出一点汗湿的痕迹。</p><p>教室里很静，只有风吹窗帘的声音，布料蹭着铁架，轻轻地响，还有远处操场落叶被风卷起的细碎声。</p><p>“她写什么了？”陈默低声问，声音压得很低。</p><p>我把信纸往下压了压，继续看，手背贴着桌面，凉意一点点渗进来。</p><blockquote><p>她写：想冷静一阵，想把脚步放慢，把心里缠在一起的线解开，想一个人去走走雾山市的老街，看看旧门板与晒着的被单，去把那盘旧的课文录音带听完 她写：心里装得太多就会看不清，她把海盐糖分给全班，唯独没有留给我，因为甜的东西吃多了，也会想哭</p></blockquote><p>读到这句，我鼻子酸了一下。想起那天她站在讲台上发糖，笑着把糖放在每个人掌心，轮到我时，她只是看了我一眼，轻轻摇头，手在口袋里握了一下又松开。</p><p>当时我以为她忘了。现在才明白，她是故意的，她怕我接了糖会更难说分开。</p><p>顾远走进来，把一瓶热水放在我桌角，又退了出去。瓶身的凉意贴着我的手背，随后是温热的蒸汽从瓶口冒出，模糊了纸角。</p><p>信的第二页更短。她说，沈聿，请给我一点时间，让我冷静一阵，也让你喘口气。她说如果我愿意，就把那罐纸星星先替她收着，不要打开，等她想明白了，再来取。</p><p>她说，纸星星会替她看着我。最后五个字写得很轻，像怕惊动什么。</p><p>我喉咙发紧，盯着最后那行字，很久没动。墨水在那里洇开一小点，像是她写时停顿了很久，笔尖停留的印子深深的。</p><p>林小满拉过椅子坐下，轻声说：“她写的时候哭了。叶老师在办公室陪着她，什么也没问，就给她倒了热水。”</p><p>“她现在在哪？”我问，声音哑得陌生，像含着沙。</p><p>“回去了。”林小满说，“她说今晚不想见你，怕见了就说不清了，话会乱。”</p><p>陈默走过来，拍拍我的肩。他手掌宽厚，带着粉笔灰的气味，还有热水杯的暖。</p><p>“别多想。”他说，“她只是累了。”</p><p>“我知道。”我说，“就是心里空了一下。”</p><p>风从半开的窗户灌进来，信纸一角被吹起，又落下，我用手按住，凉意透进掌心，纸面贴着手纹，有点粘。</p><p>顾远靠在门框上，问：“那你打算怎么办？”</p><p>“她让我等，我就等。”我说，手指把信纸的折痕又压了一遍，让它更平，“她让我冷静，我就冷静，把线理好。”</p><p>“这才像话。”顾远说，“距离有时候也是好事，近了反而看不清。”</p><p>林小满从口袋掏出一颗海盐糖，放在我面前。糖纸浅蓝，摸上去有点糙，边角被她指温捂得有点软。</p><p>“她留给你的。”她说，“最后一颗，剩下的都分光了。”</p><p>我剥开糖纸放进嘴里。咸味先化开，接着是淡甜，舌尖发麻，像秋末的海风贴着嘴唇。</p><p>“好吃吗？”她问。</p><p>“恩。”我说，“有点咸，含着舌根都紧了一下。”</p><p>我把信纸折好，放回信封，又把纸星星抚平，纹路硌着指腹，细小而真实，角尖被我按得服服帖帖。</p><p>林小满看着我，忽然说：“你们俩就像潮汐。她退的时候，你就进。她进的时候，你又退，都怕撞上。”</p><p>我低头看着信封，指腹摩挲纸面：“潮汐总会再涨上来的，对吗？”</p><p>“会的。”她说，“雾再大，太阳总会出来，潮总会回来。”</p><p>我们走出教室，走廊空荡，脚步声回响，墙上贴着的班级公约被风吹得轻晃。空气里有霉味和粉笔灰味，还有远处飘来的饭香，混在一起有点闷。</p><p>下楼遇见何晓，她抱着作业停下脚步，发梢还沾着秋雾。</p><p>“她还好吗？”她问林小满。</p><p>“还行。”林小满说，“想一个人待着，捧着热水发呆。”</p><p>何晓看向我，轻声说：“她写信给你，是信任你。她说冷静一阵，是怕把你压垮了，也怕自己垮掉。”</p><p>“我明白。”我说，把信封往外套内袋又按了按，让它贴紧胸口，“我会等她把线解开，等她回来。”</p><p>走到校门口，雾已经起来了。黄昏一过，雾就从街巷深处漫出来，裹住路灯和行人，光晕都化开。</p><p>陈默看着雾，说：“明天跑操肯定看不见人，连口令都听不清。”</p><p>“那就慢慢跑。”我说，声音轻得像对自己说，“慢点也能到。”</p><p>他又问：“那罐星星呢？给你了吗？”</p><p>“还没。”我说，“可能明天带来，她说先替她收着。”</p><p>“那可得收好了。”他说，“那是她的念想，别沾潮了。”</p><p>我点点头，手按在胸口的信封上。纸的边角隔着衣服，轻轻硌着皮肤，让人安心，心跳一下一下撞着纸面。</p><p>雾越来越浓，宋阿婆的铺子还在街口，柜台上那只保温桶冒着热气，糖罐的玻璃盖擦得发亮，暖烘烘的扑在脸上。</p><p>“去喝碗热汤吧。”陈默说，“暖暖身子，手都凉了。”</p><p>热汤端上来，碗壁烫手，蒸汽扑在脸上，带着姜香和微辣，眼睛都被熏得有点湿。我捧着碗喝了一小口，热流滑下去，胃里慢慢暖了。</p><p>宋阿婆看着我，手里还拿着汤勺：“小伙子，心里有事啊？有事就喝口热的，热的能压住慌。”</p><p>“有点。”我说，捧着碗没放下，“不过能过去，慢慢就过去了。”</p><p>“能过去就好。”她说，往我碗里又添一点，“雾再大，路总在脚下，脚步别停。”</p><p>分开后，我一个人往回走。雾沾在头发上，凉凉的，睫毛上挂着细小水珠，眨眼就掉下来。路上很静，只有脚步声和远处的潮声，像有人在远处轻轻鼓掌。</p><p>走到家楼下，我摸出那封信，又看了一遍。她的字迹在路灯下很淡，每一笔都清楚。她说把太多寄托放在我身上，她说让我冷静一阵，也让你喘口气。</p><p>我把信贴在胸口，闭上眼。风吹过耳边，带着远处潮水的声响，一下一下，像心跳。</p><p>掏钥匙时，口袋里传来很轻的一声响，像纸星星被压皱的声音。我把东西掏出来，那颗星星掉了下来，压扁了一角，纸面沁了点汗。</p><p>我捧在掌心，小心展开，又重新折好。指尖有点抖，先把纸条捋直，再一折一压，折了几次才折回原样，角尖对齐时指腹都发白了。</p><p>就在我把星星放回去时，发现信封背后还有一行很淡的字，被雾气洇得几乎看不清，铅笔痕浅浅的。</p><p>我凑近楼道窗外的光，眯眼辨认，手把信封托稳，不让风晃。那行小字写着，明晚黄昏，老地方，我把磁带带来，有话当面说。</p><p>我的心跳漏了一拍，雾气落在纸面上，把那行字晕得更淡了，指尖碰上去都怕把它擦掉。</p>',70)])])}const m=e(_,[["render",r]]);export{u as __pageData,m as default};
